WITH valid_orders AS (SELECT order_id, member_id, ordered_at, CAST(DATE_TRUNC('month', ordered_at) AS DATE) AS activity_date FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0), member_month_counts AS (SELECT member_id, activity_date, COUNT(*) AS monthly_order_count FROM valid_orders GROUP BY member_id, activity_date) SELECT v.order_id, v.member_id, v.activity_date, c.monthly_order_count FROM valid_orders v JOIN member_month_counts c ON c.member_id = v.member_id AND c.activity_date = v.activity_date